mapper.select:


    inner join sys_user u on u.user_name = trule.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    trule.del_flag = '0'
    and trule.code like concat('%', #{code}, '%')
    and trule.rule_module = #{ruleModule}
    and trule.flag = #{flag}
    and trule.name like concat('%', #{name}, '%')
    and trule.rule_type = #{ruleType}
    and trule.priority = #{priority}


${params.dataScope}
